	Y[51] = LaguerreRSICore(S12, lrs_g1_2, &lrs_o_l0, &lrs_o_l3, &lrs_o_den);	// G05 sc40
	Y[48] = lrs_o_l0;
	Y[49] = lrs_o_l3;
	Y[50] = lrs_o_den;
	Y[55] = LaguerreRSICore(S13, lrs_g1_2, &lrs_o_l0, &lrs_o_l3, &lrs_o_den);	// G05 sc100
	Y[52] = lrs_o_l0;
	Y[53] = lrs_o_l3;
