	Y[67] = LaguerreRSICore(S16, lrs_g1_2, &lrs_o_l0, &lrs_o_l3, &lrs_o_den);	// G05 of20
	Y[64] = lrs_o_l0;
	Y[65] = lrs_o_l3;
